// SearchExperimentsIter returns an iterator that iterates
// over the results of SearchExperiments.
//
// For example:
//
//	for item, err := range c.SearchExperimentsIter(ctx, &SearchExperimentsRequest{}) {
//	  if err != nil {
//	    return err
//	  }
//	  fmt.Println(item)
//	}
//
// Options opts are passed to each SearchExperiments call
// made by the iterator under the hood.
//
// Callers who need custom pagination logic should use
// SearchExperiments directly.
func (c *internalClient) SearchExperimentsIter(ctx context.Context, req *SearchExperimentsRequest, opts ...call.Option) iter.Seq2[*Experiment, error] {
	return func(yield func(*Experiment, error) bool) {
		// Deep copy the request via JSON round-trip to avoid modifying the original.
		reqBody, err := json.Marshal(req)
		if err != nil {
			yield(nil, err)
			return
		}
		pageReq := SearchExperimentsRequest{}
		if err := json.Unmarshal(reqBody, &pageReq); err != nil {
			yield(nil, err)
			return
		}
		for {
			resp, err := c.SearchExperiments(ctx, &pageReq, opts...)
			if err != nil {
				yield(nil, err)
				return
			}
			for i := range resp.Experiments {
				if !yield(&resp.Experiments[i], nil) {
					return
				}
			}
			if resp.NextPageToken == nil || *resp.NextPageToken == "" {
				return
			}
			pageReq.PageToken = resp.NextPageToken
		}
	}
}

